FUNCTION_BLOCK FB_Subsea_TransformerEsterCooling
(*
 * ==============================================================================
 * SYSTEM: DEEP-SEA SUBSEA POWER GRID INFRASTRUCTURE
 * SUBSYSTEM: HIGH-VOLTAGE STATIC SUBSEA TRANSFORMER (145 kV / 36 kV, 40 MVA)
 * MODULE: FORCED ESTER OIL CIRCULATION & HYDROSTATIC EQUALIZATION CONTROLLER
 * DEPTH RATING: 3000 METERS SEA-WATER (MSW) / ~300.0 BAR HYDROSTATIC BASELINE
 * DIELECTRIC FLUID: SYNTHETIC ORGANIC ESTER (PENTAERYTHRITOL TETRAESTER)
 * ARCHITECTURE: 2oo3 TMR PRESSURE VOTING, STATE-SPACE THERMAL KALMAN/MPC,
 *               REDUNDANT DUAL SUBMERGED CANNED-ROTOR PUMP ARBITRATION
 * ==============================================================================
 *)
VAR_INPUT
    bSystemEnable                   : BOOL;     (* Topside supervisory permissive enable signal *)
    bSafetyEStopTrip                : BOOL;     (* Active-low fail-safe trip from Subsea Protection Unit (SPU) *)
    rAmbientSeawaterPressure_bar    : REAL;     (* Hydrostatic seabed ambient pressure transmitter [bar] *)
    rInternalTankPressure_A_bar     : REAL;     (* Main tank dielectric pressure Channel A (2oo3 TMR) [bar] *)
    rInternalTankPressure_B_bar     : REAL;     (* Main tank dielectric pressure Channel B (2oo3 TMR) [bar] *)
    rInternalTankPressure_C_bar     : REAL;     (* Main tank dielectric pressure Channel C (2oo3 TMR) [bar] *)
    rBellowsStrokePosition_pct      : REAL;     (* Pressure compensator bellows physical stroke [0.0..100.0 %] *)
    rEsterBulkTemp_degC             : REAL;     (* Bulk synthetic ester dielectric oil temperature [deg C] *)
    rWindingHotSpotTemp_degC        : REAL;     (* Direct fiber-optic Bragg grating HV winding hot-spot [deg C] *)
    rHV_BusVoltage_kV               : REAL;     (* Transformer primary terminal line-to-line RMS voltage [kV] *)
    rHV_LoadCurrent_A               : REAL;     (* Transformer primary terminal line current RMS [A] *)
    rEsterFlowRate_Lpm              : REAL;     (* Forced cooling circuit electromagnetic flowmeter [L/min] *)
    rSeawaterCoolerDeltaT_degC      : REAL;     (* External finned-tube seabed cooler differential temp [deg C] *)
    rDissolvedGas_H2_ppm            : REAL;     (* Subsea online photoacoustic DGA sensor hydrogen content [ppm] *)
    rDissolvedWater_ppm             : REAL;     (* Capacitive oil moisture sensor dissolved water content [ppm] *)
    bPump1_RunningFeedback          : BOOL;     (* Canned-rotor circulation pump 1 contactor / run feedback *)
    bPump2_RunningFeedback          : BOOL;     (* Canned-rotor circulation pump 2 contactor / run feedback *)
    bResetFault                     : BOOL;     (* Topside operator latch reset / master fault acknowledge *)
END_VAR

VAR_OUTPUT
    bSystemHealthy                  : BOOL;     (* Aggregate operational health & telemetry readiness flag *)
    bEmergencyTripActive            : BOOL;     (* Discrete trip interlock to Subsea Vacuum Circuit Breaker *)
    rPump1_SpeedCmd_pct             : REAL;     (* Primary VFD speed reference setpoint [0.0..100.0 %] *)
    rPump2_SpeedCmd_pct             : REAL;     (* Redundant standby VFD speed reference setpoint [0.0..100.0 %] *)
    rDifferentialPressure_mbar      : REAL;     (* Overpressure margin relative to seabed hydrostatic [mbar] *)
    rCompensatorVolume_L            : REAL;     (* Dynamic calculated dielectric reserve volume in bellows [L] *)
    rPredictedHotSpotTemp_degC      : REAL;     (* Discrete state-space thermal model observer estimate [deg C] *)
    wTransformerStatusWord          : WORD;     (* Status bitmask: B0=Active, B1=P1, B2=P2, B3=CompOK, B4=MPC, B5=Degr *)
    wAlarmCodeWord                  : WORD;     (* Diagnostic alarm register: B0=TMR, B1=LoP, B2=HiP, B3=OT, B4=DGA *)
    rCoolingCapacityUtilized_pct    : REAL;     (* Instantaneous thermodynamic heat rejection load [0.0..100.0 %] *)
END_VAR

VAR
    (* --- 2oo3 TMR Pressure Voting Engine --- *)
    bDevAB_Valid                    : BOOL;
    bDevBC_Valid                    : BOOL;
    bDevCA_Valid                    : BOOL;
    bSensorA_Healthy                : BOOL := TRUE;
    bSensorB_Healthy                : BOOL := TRUE;
    bSensorC_Healthy                : BOOL := TRUE;
    rVotedInternalPressure_bar      : REAL;
    iHealthySensorCount             : INT := 3;

    (* --- State-Space Thermal Observer (2-State Lumped Parameter) --- *)
    (* State Vector: x1 = Winding Copper Temp [deg C], x2 = Bulk Ester Oil Temp [deg C] *)
    rState_WindingTemp_degC         : REAL := 25.0;
    rState_OilTemp_degC             : REAL := 25.0;
    rLossesCopper_kW                : REAL;
    rLossesIronCore_kW              : REAL;
    rHeatDissipated_kW              : REAL;
    rEstWindingDot                  : REAL;
    rEstOilDot                      : REAL;

    (* --- Compensator Diaphragm Kinematic Model --- *)
    rExpectedExpansion_L           : REAL;
    rActualBellowsVolume_L          : REAL;
    rCompensatorVolumeError_L       : REAL;

    (* --- MPC & Closed-Loop Flow Controller Variables --- *)
    rTempTrackingError_degC         : REAL;
    rIntegralError                  : REAL := 0.0;
    rFeedforwardFlow_Lpm            : REAL;
    rTargetFlowSetPoint_Lpm         : REAL;
    rTotalFlowCommand_pct           : REAL;

    (* --- Redundant Pump Management & Cavitation Monitoring --- *)
    bActivePumpIsPump1              : BOOL := TRUE;
    rPumpHours_1                    : REAL := 0.0;
    rPumpHours_2                    : REAL := 0.0;
    bCavitationRiskDetected         : BOOL := FALSE;

    (* --- Operational State Machine --- *)
    iOperatingState                 : INT := 0;

    (* --- Timing and Protection Blocks --- *)
    tStartupDwell                   : TON;
    tSensorFaultDebounce            : TON;
    tPressureTransientFilter        : TON;
    tOverheatTripDebounce           : TON;
    tPumpSwitchoverDelay            : TON;
    tDegasAlarmTimer                : TON;
END_VAR

(*
 * CONSTANTS AND PARAMETERS:
 * Sample Period dt = 0.050 s (50 ms real-time cyclic task)
 * Rated Voltage V_rated = 145.0 kV, Rated Current I_rated = 160.0 A (40 MVA)
 * Copper Resistance R_cu = 0.285 Ohm/phase at reference temp
 * No-load Core Loss P_fe_rated = 32.5 kW
 * Ester Specific Heat Capacity c_p = 1.88 kJ/(kg*K), Density rho = 970 kg/m^3
 * Compensator Full Stroke Displacement Volume = 450.0 Liters
 * Total Fluid Charge = 18,500 Liters
 * Thermal Expansion Coefficient Beta_ester = 0.00075 1/K
 * Nominal Target Differential Overpressure = +250.0 mbar (+0.25 bar)
 *)

(* === MAIN LOGIC EXECUTION === *)

(* ------------------------------------------------------------------------- *)
(* SECTION 1: FAIL-SAFE INTERLOCK EVALUATION                                 *)
(* ------------------------------------------------------------------------- *)
IF NOT bSafetyEStopTrip THEN
    (* Immediate de-energization interlock triggered by subsea safety relay *)
    bEmergencyTripActive := TRUE;
    bSystemHealthy := FALSE;
    rPump1_SpeedCmd_pct := 0.0;
    rPump2_SpeedCmd_pct := 0.0;
    wAlarmCodeWord := wAlarmCodeWord OR 16#8000; (* Bit 15: Emergency Stop Active *)
    iOperatingState := 99; (* Lockout state *)
    RETURN;
END_IF;

(* ------------------------------------------------------------------------- *)
(* SECTION 2: 2oo3 TRIPLE MODULAR REDUNDANT (TMR) PRESSURE VOTING ALGORITHM  *)
(* ------------------------------------------------------------------------- *)
(* Transmitter deviation threshold: 0.65 bar (allowable sensor drift at 300 bar) *)
bDevAB_Valid := ABS(rInternalTankPressure_A_bar - rInternalTankPressure_B_bar) <= 0.65;
bDevBC_Valid := ABS(rInternalTankPressure_B_bar - rInternalTankPressure_C_bar) <= 0.65;
bDevCA_Valid := ABS(rInternalTankPressure_C_bar - rInternalTankPressure_A_bar) <= 0.65;

(* Evaluate individual transmitter health states *)
bSensorA_Healthy := bDevAB_Valid OR bDevCA_Valid;
bSensorB_Healthy := bDevAB_Valid OR bDevBC_Valid;
bSensorC_Healthy := bDevBC_Valid OR bDevCA_Valid;

iHealthySensorCount := BOOL_TO_INT(bSensorA_Healthy) + BOOL_TO_INT(bSensorB_Healthy) + BOOL_TO_INT(bSensorC_Healthy);

IF iHealthySensorCount = 3 THEN
    (* All channels consistent: 2oo3 median voting selection *)
    IF (rInternalTankPressure_A_bar >= rInternalTankPressure_B_bar AND rInternalTankPressure_A_bar <= rInternalTankPressure_C_bar) OR
       (rInternalTankPressure_A_bar >= rInternalTankPressure_C_bar AND rInternalTankPressure_A_bar <= rInternalTankPressure_B_bar) THEN
        rVotedInternalPressure_bar := rInternalTankPressure_A_bar;
    ELSIF (rInternalTankPressure_B_bar >= rInternalTankPressure_A_bar AND rInternalTankPressure_B_bar <= rInternalTankPressure_C_bar) OR
          (rInternalTankPressure_B_bar >= rInternalTankPressure_C_bar AND rInternalTankPressure_B_bar <= rInternalTankPressure_A_bar) THEN
        rVotedInternalPressure_bar := rInternalTankPressure_B_bar;
    ELSE
        rVotedInternalPressure_bar := rInternalTankPressure_C_bar;
    END_IF;
    wAlarmCodeWord := wAlarmCodeWord AND NOT 16#0001; (* Clear TMR mismatch alarm *)
ELSIF iHealthySensorCount = 2 THEN
    (* Degradation to 1oo2 average of surviving redundant pair *)
    IF bSensorA_Healthy AND bSensorB_Healthy THEN
        rVotedInternalPressure_bar := (rInternalTankPressure_A_bar + rInternalTankPressure_B_bar) * 0.5;
    ELSIF bSensorB_Healthy AND bSensorC_Healthy THEN
        rVotedInternalPressure_bar := (rInternalTankPressure_B_bar + rInternalTankPressure_C_bar) * 0.5;
    ELSE
        rVotedInternalPressure_bar := (rInternalTankPressure_A_bar + rInternalTankPressure_C_bar) * 0.5;
    END_IF;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0001; (* Set Degraded TMR warning bit 0 *)
ELSIF iHealthySensorCount = 1 THEN
    (* Severe degradation: 1oo1 single sensor fall-through *)
    IF bSensorA_Healthy THEN
        rVotedInternalPressure_bar := rInternalTankPressure_A_bar;
    ELSIF bSensorB_Healthy THEN
        rVotedInternalPressure_bar := rInternalTankPressure_B_bar;
    ELSE
        rVotedInternalPressure_bar := rInternalTankPressure_C_bar;
    END_IF;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0001;
ELSE
    (* Total sensor failure: Fallback to ambient plus calibrated offset *)
    rVotedInternalPressure_bar := rAmbientSeawaterPressure_bar + 0.25;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0003; (* Bit 0 and Bit 1 critical *)
END_IF;

(* Calculate instantaneous differential overpressure in millibar *)
rDifferentialPressure_mbar := (rVotedInternalPressure_bar - rAmbientSeawaterPressure_bar) * 1000.0;

(* ------------------------------------------------------------------------- *)
(* SECTION 3: BELLOWS KINEMATICS & DIELECTRIC VOLUME INTEGRITY MONITOR       *)
(* ------------------------------------------------------------------------- *)
(* Full stroke stroke maps 0..100% to 0..450 Liters *)
rActualBellowsVolume_L := (rBellowsStrokePosition_pct / 100.0) * 450.0;
rCompensatorVolume_L := rActualBellowsVolume_L;

(* Theoretical thermal expansion of 18,500 L ester charge relative to 20 deg C baseline *)
rExpectedExpansion_L := 18500.0 * 0.00075 * (rEsterBulkTemp_degC - 20.0) + 180.0;
rCompensatorVolumeError_L := rActualBellowsVolume_L - rExpectedExpansion_L;

(* Evaluate volume divergence: deviation > 45 L implies leak or seawater ingress *)
IF ABS(rCompensatorVolumeError_L) > 45.0 THEN
    wAlarmCodeWord := wAlarmCodeWord OR 16#0040; (* Bit 6: Compensator Volume Discrepancy *)
ELSE
    wAlarmCodeWord := wAlarmCodeWord AND NOT 16#0040;
END_IF;

(* ------------------------------------------------------------------------- *)
(* SECTION 4: DISCRETE CYBER-PHYSICAL STATE-SPACE THERMAL OBSERVER           *)
(* Continuous model:                                                         *)
(*   C_winding * dT_w/dt = P_cu - G_wo*(T_w - T_oil)                         *)
(*   C_oil * dT_oil/dt   = P_fe + G_wo*(T_w - T_oil) - Q_seawater_cooler     *)
(* Discretized via forward Euler with dt = 0.050 s                           *)
(* ------------------------------------------------------------------------- *)
(* Instantaneous Joule heating / copper losses [kW] *)
rLossesCopper_kW := 3.0 * (rHV_LoadCurrent_A * rHV_LoadCurrent_A) * 0.285 / 1000.0;

(* No-load core hysteresis and eddy current losses [kW] *)
IF rHV_BusVoltage_kV > 5.0 THEN
    rLossesIronCore_kW := 32.5 * (rHV_BusVoltage_kV / 145.0) * (rHV_BusVoltage_kV / 145.0);
ELSE
    rLossesIronCore_kW := 0.0;
END_IF;

(* Convective heat extraction rate via external finned subsea exchanger [kW] *)
(* Q = mass_flow * c_p * deltaT = (Flow_Lpm / 60 * rho) * c_p * deltaT *)
rHeatDissipated_kW := (rEsterFlowRate_Lpm / 60.0 * 0.97) * 1.88 * rSeawaterCoolerDeltaT_degC;

(* State differential calculation: C_w = 420.0 kJ/K, G_wo = 18.5 kW/K, C_oil = 33800.0 kJ/K *)
rEstWindingDot := (rLossesCopper_kW - 18.5 * (rState_WindingTemp_degC - rState_OilTemp_degC)) / 420.0;
rEstOilDot := (rLossesIronCore_kW + 18.5 * (rState_WindingTemp_degC - rState_OilTemp_degC) - rHeatDissipated_kW) / 33800.0;

(* State vector update with numerical integration *)
rState_WindingTemp_degC := rState_WindingTemp_degC + rEstWindingDot * 0.050;
rState_OilTemp_degC := rState_OilTemp_degC + rEstOilDot * 0.050;

(* Kalman correction blend with physical fiber-optic sensor reading *)
rPredictedHotSpotTemp_degC := (rState_WindingTemp_degC * 0.65) + (rWindingHotSpotTemp_degC * 0.35);

(* Thermodynamic cooling capacity utilization estimation *)
rCoolingCapacityUtilized_pct := LIMIT(0.0, ((rLossesCopper_kW + rLossesIronCore_kW) / 380.0) * 100.0, 100.0);

(* ------------------------------------------------------------------------- *)
(* SECTION 5: MODEL PREDICTIVE & FEED-FORWARD FORCED CIRCULATION CONTROLLER  *)
(* ------------------------------------------------------------------------- *)
(* Fast feed-forward flow requirement based on electrical load current *)
rFeedforwardFlow_Lpm := (rHV_LoadCurrent_A / 160.0) * 620.0;

(* Feedback control on synthetic ester hotspot setpoint (target: 78.0 deg C) *)
rTempTrackingError_degC := rPredictedHotSpotTemp_degC - 78.0;

IF rTempTrackingError_degC > 0.0 THEN
    rIntegralError := LIMIT(-100.0, rIntegralError + (rTempTrackingError_degC * 0.050), 300.0);
ELSE
    rIntegralError := LIMIT(0.0, rIntegralError - 0.02, 300.0);
END_IF;

rTargetFlowSetPoint_Lpm := rFeedforwardFlow_Lpm + (rTempTrackingError_degC * 16.5) + (rIntegralError * 0.85);
rTargetFlowSetPoint_Lpm := LIMIT(120.0, rTargetFlowSetPoint_Lpm, 850.0);

(* Convert volumetric flow setpoint to normalized VFD pump speed % *)
rTotalFlowCommand_pct := LIMIT(15.0, (rTargetFlowSetPoint_Lpm / 850.0) * 100.0, 100.0);

(* ------------------------------------------------------------------------- *)
(* SECTION 6: PUMP CAVITATION & SUCTION PRESSURE SUPERVISION                 *)
(* Canned motor pumps require minimum positive head over oil vapor pressure  *)
(* ------------------------------------------------------------------------- *)
IF rDifferentialPressure_mbar < 45.0 THEN
    bCavitationRiskDetected := TRUE;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0020; (* Bit 5: Cavitation alert *)
    rTotalFlowCommand_pct := LIMIT(15.0, rTotalFlowCommand_pct, 45.0); (* Throttle max speed *)
ELSE
    bCavitationRiskDetected := FALSE;
    wAlarmCodeWord := wAlarmCodeWord AND NOT 16#0020;
END_IF;

(* ------------------------------------------------------------------------- *)
(* SECTION 7: MULTI-STAGE CYBER-PHYSICAL STATE MACHINE                       *)
(* ------------------------------------------------------------------------- *)
CASE iOperatingState OF
    0: (* STATE_INIT_DIAGNOSTICS: Cold subsea boot & integrity verification *)
        bSystemHealthy := FALSE;
        bEmergencyTripActive := FALSE;
        rPump1_SpeedCmd_pct := 0.0;
        rPump2_SpeedCmd_pct := 0.0;

        tStartupDwell(IN := bSystemEnable, PT := T#4S);
        IF tStartupDwell.Q AND (iHealthySensorCount >= 2) AND (rDifferentialPressure_mbar >= 100.0) THEN
            tStartupDwell(IN := FALSE);
            iOperatingState := 10; (* Proceed to hydrostatic equalization check *)
        END_IF;

    10: (* STATE_EQUALIZATION_EQUILIBRATE: Hydrostatic validation *)
        IF (rDifferentialPressure_mbar >= 150.0) AND (rDifferentialPressure_mbar <= 550.0) THEN
            IF (rBellowsStrokePosition_pct >= 10.0) AND (rBellowsStrokePosition_pct <= 90.0) THEN
                iOperatingState := 20; (* Pressure chamber integrity verified *)
            END_IF;
        ELSIF rDifferentialPressure_mbar < 60.0 THEN
            wAlarmCodeWord := wAlarmCodeWord OR 16#0002; (* Underpressure alarm *)
            iOperatingState := 60; (* Divert to breach containment *)
        END_IF;

    20: (* STATE_PRE_FLUX_CIRCULATION_PRIMING: Canned pump dynamic degassing *)
        bSystemHealthy := TRUE;
        bActivePumpIsPump1 := TRUE;
        rPump1_SpeedCmd_pct := 25.0; (* Low priming speed *)
        rPump2_SpeedCmd_pct := 0.0;

        tStartupDwell(IN := bPump1_RunningFeedback, PT := T#6S);
        IF tStartupDwell.Q AND (rEsterFlowRate_Lpm >= 100.0) THEN
            tStartupDwell(IN := FALSE);
            iOperatingState := 30; (* Forced circulation established *)
        END_IF;

    30: (* STATE_NORMAL_FORCED_COOLING_MPC: Advanced closed-loop thermal tracking *)
        bSystemHealthy := TRUE;
        bEmergencyTripActive := FALSE;

        (* Duty pump selection and VFD speed modulation *)
        IF bActivePumpIsPump1 THEN
            rPump1_SpeedCmd_pct := rTotalFlowCommand_pct;
            rPump2_SpeedCmd_pct := 0.0;
            rPumpHours_1 := rPumpHours_1 + 0.0000138; (* 50ms cycle to hours *)

            (* Watchdog on running feedback *)
            IF NOT bPump1_RunningFeedback THEN
                tPumpSwitchoverDelay(IN := TRUE, PT := T#1S500MS);
                IF tPumpSwitchoverDelay.Q THEN
                    tPumpSwitchoverDelay(IN := FALSE);
                    bActivePumpIsPump1 := FALSE; (* Failover to Pump 2 *)
                    iOperatingState := 50;
                END_IF;
            ELSE
                tPumpSwitchoverDelay(IN := FALSE);
            END_IF;
        ELSE
            rPump1_SpeedCmd_pct := 0.0;
            rPump2_SpeedCmd_pct := rTotalFlowCommand_pct;
            rPumpHours_2 := rPumpHours_2 + 0.0000138;

            IF NOT bPump2_RunningFeedback THEN
                tPumpSwitchoverDelay(IN := TRUE, PT := T#1S500MS);
                IF tPumpSwitchoverDelay.Q THEN
                    tPumpSwitchoverDelay(IN := FALSE);
                    bActivePumpIsPump1 := TRUE; (* Return failover *)
                    iOperatingState := 50;
                END_IF;
            ELSE
                tPumpSwitchoverDelay(IN := FALSE);
            END_IF;
        END_IF;

        (* High-load boost detection *)
        IF rPredictedHotSpotTemp_degC > 88.0 THEN
            iOperatingState := 40;
        END_IF;

    40: (* STATE_HIGH_LOAD_TURBO_BOOST: Dual-pump parallel peak heat rejection *)
        bSystemHealthy := TRUE;
        rPump1_SpeedCmd_pct := 95.0;
        rPump2_SpeedCmd_pct := 95.0;

        (* De-escalation condition once thermal transient decays *)
        IF (rPredictedHotSpotTemp_degC < 80.0) AND (rHV_LoadCurrent_A < 140.0) THEN
            iOperatingState := 30;
        END_IF;

        (* High hotspot emergency trip debounce *)
        tOverheatTripDebounce(IN := (rWindingHotSpotTemp_degC > 110.0), PT := T#3S);
        IF tOverheatTripDebounce.Q THEN
            tOverheatTripDebounce(IN := FALSE);
            wAlarmCodeWord := wAlarmCodeWord OR 16#0008; (* Overtemperature trip bit 3 *)
            iOperatingState := 99;
        END_IF;

    50: (* STATE_DEGRADED_SINGLE_PUMP_FAILOVER: Graceful degradation mode *)
        wTransformerStatusWord := wTransformerStatusWord OR 16#0020; (* Set Degraded bit 5 *)
        IF bActivePumpIsPump1 THEN
            rPump1_SpeedCmd_pct := LIMIT(0.0, rTotalFlowCommand_pct * 1.15, 100.0);
            rPump2_SpeedCmd_pct := 0.0;
        ELSE
            rPump1_SpeedCmd_pct := 0.0;
            rPump2_SpeedCmd_pct := LIMIT(0.0, rTotalFlowCommand_pct * 1.15, 100.0);
        END_IF;

        (* Re-evaluate if both pumps fail *)
        IF (NOT bPump1_RunningFeedback) AND (NOT bPump2_RunningFeedback) THEN
            tPumpSwitchoverDelay(IN := TRUE, PT := T#4S);
            IF tPumpSwitchoverDelay.Q THEN
                tPumpSwitchoverDelay(IN := FALSE);
                wAlarmCodeWord := wAlarmCodeWord OR 16#0100; (* Dual pump failure bit 8 *)
                iOperatingState := 99; (* Trip to protect windings from thermal runaway *)
            END_IF;
        END_IF;

    60: (* STATE_CRITICAL_PRESSURE_BREACH_MITIGATION: Low differential pressure *)
        bSystemHealthy := FALSE;
        (* Derate pumps to prevent negative differential suction drawing seawater through seals *)
        rPump1_SpeedCmd_pct := 20.0;
        rPump2_SpeedCmd_pct := 0.0;

        tPressureTransientFilter(IN := (rDifferentialPressure_mbar < 25.0), PT := T#2S);
        IF tPressureTransientFilter.Q THEN
            tPressureTransientFilter(IN := FALSE);
            bEmergencyTripActive := TRUE;
            wAlarmCodeWord := wAlarmCodeWord OR 16#0004; (* Critical pressure breach bit 2 *)
            iOperatingState := 99;
        END_IF;

    99: (* STATE_EMERGENCY_SHUTDOWN_LATCHED: Hardwired lockout *)
        bEmergencyTripActive := TRUE;
        bSystemHealthy := FALSE;
        rPump1_SpeedCmd_pct := 0.0;
        rPump2_SpeedCmd_pct := 0.0;

        IF bResetFault AND bSafetyEStopTrip AND (rDifferentialPressure_mbar > 80.0) THEN
            wAlarmCodeWord := 16#0000;
            bEmergencyTripActive := FALSE;
            iOperatingState := 0; (* Cold restart *)
        END_IF;

    ELSE
        iOperatingState := 99;
END_CASE;

(* ------------------------------------------------------------------------- *)
(* SECTION 8: DGA & DIELECTRIC MOISTURE MONITORING                           *)
(* ------------------------------------------------------------------------- *)
tDegasAlarmTimer(IN := (rDissolvedGas_H2_ppm > 85.0) OR (rDissolvedWater_ppm > 45.0), PT := T#10S);
IF tDegasAlarmTimer.Q THEN
    wAlarmCodeWord := wAlarmCodeWord OR 16#0010; (* DGA warning bit 4 *)
END_IF;

(* ------------------------------------------------------------------------- *)
(* SECTION 9: STATUS WORD SYNTHESIS                                          *)
(* ------------------------------------------------------------------------- *)
wTransformerStatusWord.0 := (iOperatingState > 0) AND (iOperatingState < 99); (* System Active *)
wTransformerStatusWord.1 := bPump1_RunningFeedback;                           (* Pump 1 Online *)
wTransformerStatusWord.2 := bPump2_RunningFeedback;                           (* Pump 2 Online *)
wTransformerStatusWord.3 := (rDifferentialPressure_mbar >= 100.0) AND (rDifferentialPressure_mbar <= 600.0); (* Pressure In Range *)
wTransformerStatusWord.4 := (iOperatingState = 30);                           (* MPC Nominal Control *)
wTransformerStatusWord.5 := (iHealthySensorCount < 3) OR (iOperatingState = 50); (* Degraded Mode *)
wTransformerStatusWord.6 := bCavitationRiskDetected;                          (* Cavitation Margin Low *)
wTransformerStatusWord.7 := bEmergencyTripActive;                             (* Emergency Tripped *)

END_FUNCTION_BLOCK
